<?php
namespace Tests\Feature;
use App\Models\ApiSession; use App\Models\Permission; use App\Models\Role; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Str; use Tests\TestCase;
class LeaseApiTest extends TestCase { use RefreshDatabase;
 public function test_lease_activation_generates_receivable_and_blocks_overlap():void{$org=(string)Str::uuid();DB::table('organizations')->insert(['id'=>$org,'name'=>'Test','timezone'=>'Asia/Riyadh','default_currency'=>'SAR','created_at'=>now(),'updated_at'=>now()]);$u=User::create(['organization_id'=>$org,'name'=>'Manager','full_name'=>'Manager','email'=>'lease@test.local','password'=>Hash::make('password-long-enough'),'status'=>'active']);$p=Permission::create(['id'=>(string)Str::uuid(),'code'=>'leases.manage','name'=>'Leases','module'=>'leases']);$v=Permission::create(['id'=>(string)Str::uuid(),'code'=>'leases.view','name'=>'Leases view','module'=>'leases']);$r=Role::create(['id'=>(string)Str::uuid(),'organization_id'=>$org,'code'=>'manager','name'=>'Manager']);$r->permissions()->sync([$p->id,$v->id]);$u->roles()->attach($r);$token=Str::random(80);ApiSession::create(['id'=>(string)Str::uuid(),'user_id'=>$u->id,'organization_id'=>$org,'token_hash'=>hash('sha256',$token),'expires_at'=>now()->addHour()]);$owner=(string)Str::uuid();$tenant=(string)Str::uuid();$property=(string)Str::uuid();$space=(string)Str::uuid();DB::table('owners')->insert(['id'=>$owner,'organization_id'=>$org,'code'=>'O1','full_name'=>'Owner','national_id_or_iqama'=>'1','mobile'=>'1','city'=>'Riyadh','status'=>'active','version'=>1,'created_at'=>now(),'updated_at'=>now()]);DB::table('tenants')->insert(['id'=>$tenant,'organization_id'=>$org,'code'=>'T1','full_name'=>'Tenant','national_id_or_iqama'=>'2','mobile'=>'2','status'=>'active','version'=>1,'created_at'=>now(),'updated_at'=>now()]);DB::table('properties')->insert(['id'=>$property,'organization_id'=>$org,'owner_id'=>$owner,'code'=>'P1','name'=>'Property','property_type'=>'residential','city'=>'Riyadh','district'=>'North','status'=>'active','version'=>1,'created_at'=>now(),'updated_at'=>now()]);DB::table('property_spaces')->insert(['id'=>$space,'organization_id'=>$org,'property_id'=>$property,'code'=>'S1','name'=>'Space','space_type'=>'unit','status'=>'active','version'=>1,'created_at'=>now(),'updated_at'=>now()]);$payload=['internalNumber'=>'L1','tenantId'=>$tenant,'startDate'=>'2026-01-01','endDate'=>'2026-12-31','annualRent'=>1200,'totalValue'=>1200,'frequency'=>'one_time','spaces'=>[['spaceId'=>$space,'startDate'=>'2026-01-01','endDate'=>'2026-12-31']],'installments'=>[['dueDate'=>'2026-01-01','amount'=>1200]]];$lease=$this->withToken($token)->postJson('/v1/leases',$payload)->assertCreated()->json('data');$this->withToken($token)->postJson('/v1/leases/'.$lease['id'].'/activate')->assertOk()->assertJsonPath('data.status','active');$this->assertDatabaseCount('receivables',1);$duplicate=[...$payload,'internalNumber'=>'L2'];$other=$this->withToken($token)->postJson('/v1/leases',$duplicate)->assertCreated()->json('data');$this->withToken($token)->postJson('/v1/leases/'.$other['id'].'/activate')->assertConflict();}}
